"""Builds the test corpus: tests/fixtures/pdfs/*.pdf, manifest.json and tests/fixtures/assets/*.

    pip install pymupdf reportlab fonttools pillow numpy matplotlib playwright
    python tests/fixtures/gen/generate.py

Needs a Playwright Chromium (`npx playwright install chromium`). No network access and no system fonts:
every glyph comes from fonts bundled inside those Python packages (see fonts.py), and all text is invented.
The 300 page document is not committed; the tests build it on demand (tests/integration/helpers.ts).
"""

import json
import shutil
import sys

import chromium_docs
import common
import derived_docs
import raw_docs
import reportlab_docs

NOTICE = (
    "Generated by tests/fixtures/gen/generate.py. Synthetic text only. Embedded font subsets: Noto (SIL OFL 1.1), "
    "Droid Sans Fallback (Apache 2.0), DejaVu (DejaVu licence), PDF base-14 substitutes."
)


def main() -> int:
    if common.OUT.exists():
        shutil.rmtree(common.OUT)
    common.OUT.mkdir(parents=True)
    reportlab_docs.build()
    raw_docs.build()
    chromium_docs.build()
    derived_docs.build()
    manifest = {"version": 1, "notice": NOTICE, "documents": sorted(common.documents, key=lambda d: d["id"])}
    (common.OUT / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=1) + "\n",
                                              encoding="utf-8", newline="\n")
    total = sum(f.stat().st_size for f in common.OUT.iterdir())
    print(f"{len(common.documents)} documents, {total / 1e6:.2f} MB")
    if total > 15e6:
        print("corpus is over the 15 MB budget", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
